def find_conflicts(sessions: Sequence[Session]) -> List[Tuple[Session, Session]]:
    """Return every pair of sessions that clash (same room or group, overlapping time).
    The list is ordered by the position of the first session in the input list,
    and each pair appears only once with the earlier session first.
    """
    conflicts: List[Tuple[Session, Session]] = []
    for i, a in enumerate(sessions):
        for b in sessions[i+1:]:
            # Sessions must be on the same day
            if a.day != b.day:
                continue
            # Overlap must be genuine (touching endpoints does not count)
            if not a.overlaps(b):
                continue
            # They must share a room or a student group
            if not _shares_resource(a, b):
                continue
            conflicts.append((a, b))
    return conflicts
